def is_task_schedulable(task_i):
    R_i = calculate_worst_case_response_time(task_i)
    if R_i <= task_i.D:
        return True
    else:
        return False

def is_optimal_policy(policy_P, system_model, all_other_policies):
    for system in systems_compliant_with(system_model):
        for policy_Q in all_other_policies:
            if policy_Q.find_schedulable_ordering(system):
                if not policy_P.find_schedulable_ordering(system):
                    return False # P is not optimal
    return True # P is optimal

def is_robust_policy(policy_P, system_model, interference_function, all_other_policies):
    for system in systems_compliant_with(system_model):
        for policy_Q in all_other_policies:
            alpha_Q = policy_Q.max_tolerable_interference(system, interference_function)
            if alpha_Q is not None: # System is schedulable and tolerates alpha_Q
                alpha_P = policy_P.max_tolerable_interference(system, interference_function)
                if alpha_P is None or alpha_P < alpha_Q:
                    return False # P is not robust
    return True # P is robust
